-- 86 The Long Corridor: a torch that came in with its hall's scene. Its
-- flicker is this script - which runs only because a streamed chunk's
-- scripts start like any scene's. Generated by tools/gen_scenes.py.

script = { tick_rate = 30 }

-- One file serves every torch, so each keeps its clock in `torches`.
local torches = {}

function init(entity)
    local x = Transform.get_position(entity) or 0
    torches[entity] = { t = 0, seed = x * 0.013 }
end

function update(entity, dt)
    local s = torches[entity]
    s.t = s.t + dt
    local f = 1.45 + 0.22 * math.sin(s.t * 13.1 + s.seed) + 0.12 * math.sin(s.t * 7.7 + s.seed * 3)
    Lighting.set_intensity(entity, f)
end
